// 5. SINCRONIZACIÓN DE CONFIGURACIÓN INSTITUCIONAL EN FIRESTORE
function escucharConfiguracion(callback) {
  const docRef = db.collection("configuracion").doc("institucion");
  return docRef.onSnapshot((doc) => {
    if (doc.exists) {
      const data = doc.data();
      const usaLogoAntiguoSVG = !data.logo || String(data.logo).startsWith("data:image/svg+xml");
      const usaNombreAntiguo = !data.nombre || data.nombre === "Colegio Excelencia San Marcos";
      const logoFinal = usaLogoAntiguoSVG ? DEFAULT_LOGO_BASE64 : data.logo;
      const nombreFinal = usaNombreAntiguo ? CONFIG_DEFECTO.nombre : data.nombre;

      if (usaLogoAntiguoSVG || usaNombreAntiguo) {
        docRef.set({ logo: logoFinal, nombre: nombreFinal }, { merge: true }).catch(() => {});
      }

      window.CONFIG_COLEGIO = {
        nombre: nombreFinal,
        lema: data.lema || CONFIG_DEFECTO.lema,
        horaLimite: data.horaLimite || CONFIG_DEFECTO.horaLimite,
        tolerancia: typeof data.tolerancia === "number" ? data.tolerancia : Number(data.tolerancia || CONFIG_DEFECTO.tolerancia),
        logo: logoFinal
      };
    } else {
      docRef.set(CONFIG_DEFECTO).catch((err) => console.error("Error inicializando config:", err));
      window.CONFIG_COLEGIO = { ...CONFIG_DEFECTO };
    }
    if (typeof callback === "function") {
      callback(window.CONFIG_COLEGIO);
    }
  }, (error) => {
    console.error("Error en snapshot de configuración:", error);
    if (typeof callback === "function") callback(window.CONFIG_COLEGIO);
  });
}

async function guardarConfiguracionEnNube(nuevaConfig) {
  const docRef = db.collection("configuracion").doc("institucion");
  await docRef.set(nuevaConfig, { merge: true });
}

// 6. SINCRONIZACIÓN DE LOS 30 ALUMNOS EN FIRESTORE
let semilleroEjecutado = false;

function escucharAlumnos(callback) {
  return db.collection("alumnos").onSnapshot(async (snapshot) => {
    if (snapshot.empty && !semilleroEjecutado) {
      semilleroEjecutado = true;
      await sembrarAlumnosIniciales();
      return;
    }
    const lista = [];
    snapshot.forEach((doc) => {
      lista.push({ id: doc.id, ...doc.data() });
    });
    lista.sort((a, b) => (a.codigo || "").localeCompare(b.codigo || ""));
    if (typeof callback === "function") {
      callback(lista);
    }
  }, (error) => {
    console.error("Error escuchando colección alumnos:", error);
    if (typeof callback === "function") callback([...ALUMNOS_SEMILLA]);
  });
}

async function sembrarAlumnosIniciales() {
  const batch = db.batch();
  ALUMNOS_SEMILLA.forEach((alumno) => {
    const ref = db.collection("alumnos").doc(alumno.codigo);
    batch.set(ref, {
      codigo: alumno.codigo,
      nombre: alumno.nombre,
      grado: alumno.grado,
      telefono: alumno.telefono,
      creadoEn: firebase.firestore.FieldValue.serverTimestamp()
    });
  });
  await batch.commit();
}

// 7. UTILIDADES DE FECHA, HORA, ESTADO Y AVATAR
function obtenerFechaHoyISO() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

function formatearFechaISOaLegible(isoStr) {
  if (!isoStr || !isoStr.includes("-")) return isoStr || "-";
  const [yyyy, mm, dd] = isoStr.split("-");
  return `${dd}/${mm}/${yyyy}`;
}

function obtenerHoraActualLegible(dateObj = new Date()) {
  return dateObj.toLocaleTimeString("es-PE", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false
  });
}

function evaluarEstadoHorario(dateObj = new Date(), config = window.CONFIG_COLEGIO) {
  const [limHora, limMin] = (config.horaLimite || "08:00").split(":").map(Number);
  const toleranciaMin = Number(config.tolerancia || 0);
  const minutosLimiteTotal = limHora * 60 + limMin + toleranciaMin;
  const minutosActuales = dateObj.getHours() * 60 + dateObj.getMinutes();
  return minutosActuales <= minutosLimiteTotal ? "PUNTUAL" : "TARDANZA";
}

function obtenerIniciales(nombreCompleto = "") {
  const partes = nombreCompleto.trim().split(/\s+/).filter(Boolean);
  if (partes.length === 0) return "AL";
  if (partes.length === 1) return partes[0].substring(0, 2).toUpperCase();
  return (partes[0][0] + partes[partes.length > 2 ? 2 : 1][0]).toUpperCase();
}

function obtenerColorAvatar(semilla = "") {
  const paleta = [
    "linear-gradient(135deg, #2563eb, #1d4ed8)",
    "linear-gradient(135deg, #059669, #10b981)",
    "linear-gradient(135deg, #7c3aed, #6d28d9)",
    "linear-gradient(135deg, #db2777, #be185d)",
    "linear-gradient(135deg, #ea580c, #c2410c)",
    "linear-gradient(135deg, #0891b2, #0e7490)"
  ];
  let hash = 0;
  for (let i = 0; i < semilla.length; i++) {
    hash = semilla.charCodeAt(i) + ((hash << 5) - hash);
  }
  return paleta[Math.abs(hash) % paleta.length];
}

// 8. WEB AUDIO API (SONIDOS DE ESCANEO Y SISTEMA)
const AudioFX = {
  ctx: null,
  init() {
    if (!this.ctx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass) this.ctx = new AudioContextClass();
    }
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume();
    }
  },
  playTone(freq, type, duration, delay = 0, gainVal = 0.18) {
    try {
      this.init();
      if (!this.ctx) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime + delay);
      gain.gain.setValueAtTime(gainVal, this.ctx.currentTime + delay);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + delay + duration);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(this.ctx.currentTime + delay);
      osc.stop(this.ctx.currentTime + delay + duration);
    } catch (e) {
      console.warn("AudioFX no disponible:", e);
    }
  },
  beepExito() {
    this.playTone(880, "sine", 0.14, 0, 0.2);
    this.playTone(1318.5, "sine", 0.22, 0.12, 0.22);
  },
  beepTardanza() {
    this.playTone(587.33, "triangle", 0.16, 0, 0.22);
    this.playTone(440, "triangle", 0.26, 0.15, 0.22);
  },
  beepDuplicado() {
    this.playTone(220, "sawtooth", 0.18, 0, 0.2);
    this.playTone(174.61, "sawtooth", 0.28, 0.18, 0.22);
  }
};

// 9. SÍNTESIS DE VOZ (window.speechSynthesis)
const VozFX = {
  hablar(mensaje, habilitado = true) {
    if (!habilitado || !("speechSynthesis" in window)) return;
    try {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(mensaje);
      utterance.lang = "es-PE";
      utterance.rate = 1.04;
      utterance.pitch = 1.0;
      const voces = window.speechSynthesis.getVoices();
      const vozEs = voces.find((v) => v.lang.startsWith("es"));
      if (vozEs) utterance.voice = vozEs;
      window.speechSynthesis.speak(utterance);
    } catch (e) {
      console.warn("Síntesis de voz no disponible:", e);
    }
  }
};

// 10. NOTIFICACIONES TOAST FLOTANTES Y TEMA CLARO/OSCURO
function mostrarToast(titulo, mensaje = "", tipo = "info") {
  let container = document.getElementById("toast-container");
  if (!container) {
    container = document.createElement("div");
    container.id = "toast-container";
    document.body.appendChild(container);
  }
  const iconos = {
    success: "fa-solid fa-circle-check",
    error: "fa-solid fa-circle-xmark",
    warning: "fa-solid fa-triangle-exclamation",
    info: "fa-solid fa-circle-info"
  };
  const colores = {
    success: "var(--success)",
    error: "var(--danger)",
    warning: "var(--warning)",
    info: "var(--primary)"
  };

  const toast = document.createElement("div");
  toast.className = `saas-toast ${tipo}`;
  toast.innerHTML = `
    <i class="${iconos[tipo] || iconos.info}" style="color:${colores[tipo] || colores.info}; font-size:1.25rem; margin-top:2px;"></i>
    <div style="flex:1;">
      <div style="font-weight:700; font-size:0.88rem;">${titulo}</div>
      ${mensaje ? `<div style="font-size:0.8rem; color:var(--text-secondary); margin-top:2px;">${mensaje}</div>` : ""}
    </div>
  `;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateX(30px)";
    toast.style.transition = "all 0.25s ease";
    setTimeout(() => toast.remove(), 260);
  }, 3800);
}

function inicializarTema() {
  const guardado = localStorage.getItem("saas_qr_theme") || "light";
  aplicarTema(guardado);
}

function aplicarTema(tema) {
  document.documentElement.setAttribute("data-theme", tema);
  localStorage.setItem("saas_qr_theme", tema);
  const botones = document.querySelectorAll(".btn-theme-toggle i");
  botones.forEach((icon) => {
    icon.className = tema === "dark" ? "fa-solid fa-sun" : "fa-solid fa-moon";
  });
}

function alternarTema() {
  const actual = document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light";
  const nuevo = actual === "dark" ? "light" : "dark";
  aplicarTema(nuevo);
  window.dispatchEvent(new CustomEvent("themeChanged", { detail: { theme: nuevo } }));
}

function construirUrlWhatsApp(telefono, alumnoNombre, grado, fechaLegible, horaLegible, estado) {
  const limpio = String(telefono || "51987654301").replace(/\D/g, "");
  const colegio = (window.CONFIG_COLEGIO && window.CONFIG_COLEGIO.nombre) || CONFIG_DEFECTO.nombre;
  const texto = `Estimado padre de familia del *${colegio}*, le informamos que su hijo(a) *${alumnoNombre}* de *${grado}* registró su ingreso el *${fechaLegible}* a las *${horaLegible}* con estado: *${estado}*.`;
  return `https://wa.me/${limpio}?text=${encodeURIComponent(texto)}`;
}
